using System.Collections.Frozen;
using System.Runtime.InteropServices;

namespace CatalogSvc;

public readonly record struct ProductInfo(string Category, decimal Price);

public class ProductCatalog
{
    private readonly Dictionary<string, ProductInfo> _products = new(StringComparer.OrdinalIgnoreCase);

    // Reverse index: category → set of product codes
    private readonly Dictionary<string, HashSet<string>> _categoryIndex =
        new(StringComparer.OrdinalIgnoreCase);

    public void AddProduct(string code, string category, decimal price)
    {
        if (_products.TryGetValue(code, out var existing))
            _categoryIndex[existing.Category].Remove(code);

        _products[code] = new ProductInfo(category, price);

        ref var set = ref CollectionsMarshal.GetValueRefOrAddDefault(
            _categoryIndex, category, out bool exists);
        set ??= new HashSet<string>(StringComparer.OrdinalIgnoreCase);
        set.Add(code);
    }

    public string? GetCategory(string code)
        => _products.TryGetValue(code, out var info) ? info.Category : null;

    public decimal GetTotalPrice(IEnumerable<string> codes)
    {
        decimal total = 0m;
        foreach (var code in codes)
        {
            if (_products.TryGetValue(code, out var info))
                total += info.Price;
        }
        return total;
    }

    // O(1) lookup via reverse index instead of O(n) scan
    public List<string> GetProductsByCategory(string category)
        => _categoryIndex.TryGetValue(category, out var set)
            ? [.. set]
            : [];

    /// <summary>
    /// Returns a frozen snapshot optimized for high-throughput reads.
    /// FrozenDictionary uses a perfect hash function for faster lookups.
    /// </summary>
    public FrozenProductCatalog Freeze() => new(_products, _categoryIndex);
}

/// <summary>
/// Immutable, read-optimized catalog using FrozenDictionary for
/// maximum lookup throughput after the catalog is fully built.
/// </summary>
public class FrozenProductCatalog
{
    private readonly FrozenDictionary<string, ProductInfo> _products;
    private readonly FrozenDictionary<string, string[]> _categoryIndex;

    internal FrozenProductCatalog(
        Dictionary<string, ProductInfo> products,
        Dictionary<string, HashSet<string>> categoryIndex)
    {
        _products = products.ToFrozenDictionary(StringComparer.OrdinalIgnoreCase);
        _categoryIndex = categoryIndex.ToFrozenDictionary(
            kvp => kvp.Key,
            kvp => kvp.Value.ToArray(),
            StringComparer.OrdinalIgnoreCase);
    }

    public string? GetCategory(string code)
        => _products.TryGetValue(code, out var info) ? info.Category : null;

    public decimal GetTotalPrice(IEnumerable<string> codes)
    {
        decimal total = 0m;
        foreach (var code in codes)
        {
            if (_products.TryGetValue(code, out var info))
                total += info.Price;
        }
        return total;
    }

    public List<string> GetProductsByCategory(string category)
        => _categoryIndex.TryGetValue(category, out var codes)
            ? [.. codes]
            : [];
}

